/* Fixed CPython 3.14.4 exception-note transport.
 * No caller JSON traversal, type policy, request state, or recursion limit.
 * This one C call consumes a new reference for the current error, performs
 * exactly one original _json note format, and retrieves the resulting error
 * before Python/FFI dispatch can observe a pending exception indicator.
 */
#include <Python.h>
#include <string.h>

#if PY_MAJOR_VERSION != 3 || PY_MINOR_VERSION != 14 || PY_MICRO_VERSION != 4
#error This development primitive is pinned to CPython 3.14.4 headers.
#endif
#ifdef Py_GIL_DISABLED
#error This development primitive has not qualified the free-threaded ABI.
#endif

/* Exact declaration from CPython v3.14.4 Include/internal/pycore_pyerrors.h. */
PyAPI_FUNC(void) _PyErr_FormatNote(const char *format, ...);

static PyObject *
note(PyObject *module, PyObject *args)
{
    PyObject *error, *container, *key;
    int kind;
    Py_ssize_t index;
    (void)module;
    if (!PyArg_ParseTuple(args, "OiOOn:note", &error, &kind, &container, &key, &index))
        return NULL;
    if (!PyExceptionInstance_Check(error)) {
        PyErr_SetString(PyExc_TypeError, "note transport requires an actual exception instance");
        return NULL;
    }
    if (kind < 1 || kind > 3 || (kind != 2 && index != 0) ||
        (kind == 2 && (index < 0 || key != Py_None)) ||
        (kind == 3 && key != Py_None)) {
        PyErr_SetString(PyExc_ValueError, "invalid fixed exception-note transport frame");
        return NULL;
    }
    if (PyErr_Occurred() != NULL)
        return NULL;
    PyErr_SetRaisedException(Py_NewRef(error));
    if (kind == 1)
        _PyErr_FormatNote("when serializing %T item %R", container, key);
    else if (kind == 2)
        _PyErr_FormatNote("when serializing %T item %zd", container, index);
    else
        _PyErr_FormatNote("when serializing %T object", container);
    /* Format failure deliberately returns the new error with the original
     * chained by CPython itself. It is never changed into success or ignored. */
    PyObject *result = PyErr_GetRaisedException();
    if (result == NULL) {
        PyErr_SetString(PyExc_RuntimeError, "CPython note transport lost the raised exception");
        return NULL;
    }
    return result; /* New reference; normal extension return convention. */
}

static PyMethodDef methods[] = {
    {"note", note, METH_VARARGS, "One fixed original CPython JSON error note."},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef definition = {
    PyModuleDef_HEAD_INIT,
    "_hia_normalization_note_314",
    "Development-only CPython error transport; no normalization or recursion proof.",
    -1,
    methods
};

PyMODINIT_FUNC
PyInit__hia_normalization_note_314(void)
{
    if (strncmp(Py_GetVersion(), "3.14.4 ", 7) != 0) {
        PyErr_SetString(PyExc_ImportError, "note transport requires the actual CPython 3.14.4 runtime");
        return NULL;
    }
    PyObject *module = PyModule_Create(&definition);
    if (module == NULL)
        return NULL;
    if (PyModule_AddIntConstant(module, "header_hexversion", PY_VERSION_HEX) < 0 ||
        PyModule_AddStringConstant(module, "runtime_version", Py_GetVersion()) < 0) {
        Py_DECREF(module);
        return NULL;
    }
    return module;
}

