"""Actual CPython 3.14.4 fixed-C note controls, outside product source."""
from __future__ import annotations

import hashlib
import importlib.util
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import sysconfig
import time
import traceback
import weakref

ROOT = Path(__file__).resolve().parents[1]
CASE = ROOT / "evidence" / "cpython314-note-primitive-r1"
SOURCE = ROOT / "helpers" / "cpython314_note_transport.c"
MODULE = "_hia_normalization_note_314"

class ChildError(Exception):
    pass

def state(error):
    seen = set()
    def visit(value):
        if value is None:
            return None
        if id(value) in seen:
            return {"cycle": True, "type": type(value).__qualname__}
        seen.add(id(value))
        try:
            notes = BaseException.__getattribute__(value, "__notes__")
        except AttributeError:
            notes = None
        return {"type": type(value).__module__ + "." + type(value).__qualname__,
                "args": list(BaseException.__getattribute__(value, "args")),
                "notes": notes,
                "suppress_context": BaseException.__getattribute__(value, "__suppress_context__"),
                "cause": visit(BaseException.__getattribute__(value, "__cause__")),
                "context": visit(BaseException.__getattribute__(value, "__context__"))}
    return visit(error)

def fixture(name):
    events = []
    primary = ChildError("selected child error")
    replacement = KeyboardInterrupt("key repr interrupted")
    class Leaf:
        pass
    class DefaultBox:
        pass
    class FancyMap(dict):
        pass
    class FancyList(list):
        pass
    class FancyTuple(tuple):
        pass
    class Key(str):
        def __repr__(self):
            events.append("key.__repr__")
            if name == "key_repr_interrupt":
                raise replacement
            return "<original-key>"
    class OverridesAddNote(ChildError):
        def add_note(self, note):
            events.append("public add_note was called")
            raise AssertionError("C JSON must use its original internal note operation")
    leaf = Leaf()
    box = DefaultBox()
    if name == "override_public_add_note":
        primary = OverridesAddNote("selected child error")
    if name == "prior_notes":
        primary.__notes__ = ["existing note"]
    if name == "invalid_notes":
        primary.__notes__ = 42
    if name == "preexisting_chain":
        primary.__cause__ = ValueError("retained explicit cause")
        primary.__context__ = RuntimeError("retained context")
        primary.__suppress_context__ = True
    key = Key("key") if name in ("key_repr", "key_repr_interrupt") else "key"
    if name in ("list", "prior_notes", "preexisting_chain", "override_public_add_note"):
        document = [leaf]
        steps = [(2, document, None, 0)]
    elif name == "tuple":
        document = (leaf,)
        steps = [(2, document, None, 0)]
    elif name == "derived_list":
        document = FancyList([leaf])
        steps = [(2, document, None, 0)]
    elif name == "derived_tuple":
        document = FancyTuple((leaf,))
        steps = [(2, document, None, 0)]
    elif name == "derived_map":
        document = FancyMap({key: leaf})
        steps = [(1, document, key, 0)]
    elif name == "default_object":
        document = box
        steps = [(3, box, None, 0)]
    elif name == "nested":
        inner = (leaf,)
        middle = {key: inner}
        document = [middle]
        steps = [(2, inner, None, 0), (1, middle, key, 0), (2, document, None, 0)]
    else:
        document = {key: leaf}
        steps = [(1, document, key, 0)]
    calls = []
    def default(value):
        calls.append("box" if value is box else "leaf" if value is leaf else "unexpected")
        if value is box:
            return leaf
        if value is leaf:
            raise primary
        raise AssertionError("unexpected oracle object")
    return document, default, primary, replacement, steps, events, calls

def compare(name, module):
    document, default, primary, replacement, steps, events, calls = fixture(name)
    try:
        json.dumps(document, ensure_ascii=False, sort_keys=True,
                   separators=(",", ":"), allow_nan=False, default=default)
    except BaseException as original:
        original_state = state(original)
        original_identity = {"primary": original is primary, "replacement": original is replacement}
    else:
        raise AssertionError("original JSON did not fail")
    original_events, original_calls = list(events), list(calls)
    document, default, primary, replacement, steps, events, calls = fixture(name)
    result = primary
    for kind, container, key, index in steps:
        result = module.note(result, kind, container, key, index)
    observed = state(result)
    identity = {"primary": result is primary, "replacement": result is replacement}
    assert observed == original_state, (name, original_state, observed)
    assert events == original_events, (name, original_events, events)
    assert identity == original_identity, (name, original_identity, identity)
    assert calls == [], "primitive dispatched caller payload/default"
    return {"case": name, "original": original_state, "native": observed,
            "exception_identity": identity, "note_callbacks": events,
            "original_child_callbacks": original_calls,
            "primitive_child_callbacks": calls, "note_calls": len(steps)}

def retained_reference_control(module):
    error = ChildError("reference custody")
    try:
        raise error
    except ChildError:
        pass
    original_traceback = error.__traceback__
    before = sys.getrefcount(error)
    for index in range(32):
        result = module.note(error, 2, [None], None, 0)
        assert result is error and error.__traceback__ is original_traceback
        del result
        assert sys.getrefcount(error) == before, (index, before, sys.getrefcount(error))
    class Container(list):
        pass
    container = Container([None])
    held = weakref.ref(container)
    result = module.note(error, 2, container, None, 0)
    del result, container
    assert held() is None, "note transport retained the foreign container"
    return {"case": "reference_and_traceback_custody",
            "iterations": 32, "reference_count_before": before,
            "reference_count_after": sys.getrefcount(error),
            "original_traceback_identity_preserved": True,
            "container_released_without_gc": True}

def invalid_frame_control(module):
    error = ChildError("must remain unchanged")
    original = state(error)
    cases = [(0, {}, None, 0), (4, {}, None, 0), (1, {}, None, 1),
             (2, [], None, -1), (2, [], "wrong-key", 0), (3, object(), "wrong-key", 0)]
    for args in cases:
        try:
            module.note(error, *args)
        except ValueError:
            pass
        else:
            raise AssertionError("invalid note frame was accepted")
        assert state(error) == original
    return {"case": "invalid_fixed_frames", "refused": len(cases), "original_error_unchanged": True}

def main():
    CASE.mkdir(mode=0o700, exist_ok=False)
    start = time.monotonic_ns()
    original_source = SOURCE.read_bytes()
    source_sha = hashlib.sha256(original_source).hexdigest()
    runtime = {"executable": sys.executable, "version": sys.version,
               "hexversion": sys.hexversion, "SOABI": sysconfig.get_config_var("SOABI"),
               "include": sysconfig.get_path("include")}
    report = {"schema": "hia.normalization.cpython314-note-primitive.development.v1",
              "runtime": runtime, "source_sha256": source_sha,
              "normalization_owner_qualified": False,
              "physical_recursion_qualified": False,
              "whole_payload_forwarded_to_C_shim": False,
              "CPython_runtime_dependency_retained": True,
              "observations": [], "failures": []}
    compiler = shutil.which("cc")
    try:
        assert sys.version_info[:3] == (3, 14, 4), runtime
        include = Path(sysconfig.get_path("include"))
        assert (include / "Python.h").is_file(), "actual interpreter development header missing"
        assert compiler is not None, "no actual system C compiler"
        compiler = str(Path(compiler).resolve(strict=True))
        report["compiler"] = {"path": compiler,
            "sha256": hashlib.sha256(Path(compiler).read_bytes()).hexdigest()}
        target = CASE / (MODULE + sysconfig.get_config_var("EXT_SUFFIX"))
        command = [compiler, "-std=c11", "-shared", "-fPIC", "-O2", "-Wall", "-Wextra",
                   "-I", str(include), str(SOURCE), "-o", str(target)]
        report["compile_argv"] = command
        compile_result = subprocess.run(command, capture_output=True, timeout=30)
        (CASE / "compile.stdout").write_bytes(compile_result.stdout)
        (CASE / "compile.stderr").write_bytes(compile_result.stderr)
        report["compile_returncode"] = compile_result.returncode
        assert compile_result.returncode == 0, compile_result.stderr.decode("utf-8", "replace")
        report["image_sha256"] = hashlib.sha256(target.read_bytes()).hexdigest()
        spec = importlib.util.spec_from_file_location(MODULE, target)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        assert module.header_hexversion == sys.hexversion
        report["module_runtime_version"] = module.runtime_version
        cases = ("dict", "list", "tuple", "derived_map", "derived_list", "derived_tuple",
                 "default_object", "nested", "key_repr", "key_repr_interrupt",
                 "prior_notes", "invalid_notes", "preexisting_chain", "override_public_add_note")
        for name in cases:
            try:
                report["observations"].append(compare(name, module))
            except BaseException:
                report["failures"].append({"case": name, "traceback": traceback.format_exc()})
        for control in (retained_reference_control, invalid_frame_control):
            try:
                report["observations"].append(control(module))
            except BaseException:
                report["failures"].append({"case": control.__name__, "traceback": traceback.format_exc()})
    except BaseException:
        report["failures"].append({"case": "build_or_admission", "traceback": traceback.format_exc()})
    report["source_unchanged"] = SOURCE.read_bytes() == original_source
    report["elapsed_ns"] = time.monotonic_ns() - start
    report["status"] = "PASS_DEVELOPMENT_PRIMITIVE_ONLY" if not report["failures"] and report["source_unchanged"] else "FAIL"
    raw = (json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode()
    with (CASE / "RESULT.json").open("xb") as stream:
        stream.write(raw); stream.flush(); os.fsync(stream.fileno())
    print(json.dumps({"status": report["status"], "observations": len(report["observations"]),
          "failures": len(report["failures"]), "result": str(CASE / "RESULT.json"),
          "result_bytes": len(raw), "result_sha256": hashlib.sha256(raw).hexdigest(),
          "scope": "CPython314 single-C-call note mechanism only; physical recursion and normalization remain unqualified"},
          sort_keys=True))
    return 0 if report["status"] == "PASS_DEVELOPMENT_PRIMITIVE_ONLY" else 1

if __name__ == "__main__":
    raise SystemExit(main())
